import { putBand } from '@projexlight/sdk-profile';
await putBand({
  app_identity_id, band_kind: 'L2',
  payload: { locale: 'es-MX', timezone: 'America/Mexico_City' },
});

import { setSecureField } from '@projexlight/sdk-profile';
await setSecureField({
  person_id, field: 'ssn_last4', plaintext: '1234',
  set_by_persona_id, purpose: 'kyc-tax-onboarding',
});

import { getSecureField } from '@projexlight/sdk-profile';
const { plaintext } = await getSecureField({
  person_id, field: 'ssn_last4',
  caller_sdk: '@projexlight/sdk-compliance', reason: 'ofac-screen-2026-05',
});

subscribeEvents('data-rights.request.opened.v1', async (e) => {
  for (const f of await listSecureFields({ person_id: e.payload.person_id })) {
    await shredSecureField({ person_id: e.payload.person_id, field: f.name, shred_reason: 'gdpr-art-17' });
  }
});

// rate-limit fires inside getSecureField; alert path:
subscribeEvents('profile.secure.field.read.v1', async (e) => {
  if (await isAnomalousReadPattern({ persona_id: e.payload.persona_id })) {
    alertSecurity({ persona_id: e.payload.persona_id });
  }
});
